-- THE ARABIC FAQ ANSWERS EVERY QUESTION THE ENGLISH ONE DOES (22 Sep 2026, audit DL-02).
--
-- SEAT: customer_support. Data only: 130 rows into public.company_faq. No routine, no column, no grant.
--
-- MEASURED on production 22 Sep 2026:
--   company_faq public + approved:  150 English, 24 Arabic.
--   Of the 150 English records, 22 have an Arabic twin — read as the NUMBER inside source_note
--   ('Arabic mirror of company_faq id N', sometimes followed by a note). An exact-string match on that
--   sentence finds only 20, because two of the twins carry a trailing note, which is why 130 answers
--   were written for 128 gaps; a prefix match with a trailing % finds 27, because "id 2" also matches
--   the twin of id 26, and that is the bug the review caught in the guard below.
--   128 English records have no Arabic twin. fn_faq_answer answers an Arabic question ONLY from
--   language = 'ar' records — both the
--   keyword step and the corroborated semantic step filter on it — so an Arabic asker was reaching a
--   seventh of the company's approved knowledge, and everything else came back
--   {"answered":false,"reason":"no confident FAQ match"} while the English answer sat in the table.
--
-- WHAT THIS ADDS. One Arabic record per uncovered English record, same section convention ('Arabic'),
-- same audience, same approval flags, source_note naming the English id it mirrors. Written, not
-- translated (founder instruction 586, the standard of #818): formal Gulf business Arabic, the formal
-- plural, the brand in Latin letters, Arabic punctuation, and none of the artefacts
-- scripts/checks/every_arabic_message_is_written_not_translated.test.mjs names — every line here was
-- scanned by that check's own ARTEFACTS patterns before this file was written, and this file is after
-- the check's anchor in MANIFEST.txt, so it stays scanned.
--
-- THE FACTS ARE THE ENGLISH ANSWER'S FACTS. Every figure, fee, date, deadline, document and exception
-- is carried across unchanged (3% reveal fee plus the card processing fee, AED 1,000 a year from the
-- 1,001st supplier, the first 1,000 permanently exempt, no commission, the 1 GB upload limit, ...).
-- Where an answer names the licence it uses the wording the paper carries — رخصة تاجر رقم 1633275 –
-- دائرة الاقتصاد والسياحة في دبي — never the retired "E-Trader" class (same audit, DL-06).
--
-- ONE ORTHOGRAPHY, ONE NAME PER FEE (review of PR #857). The tanwin is written with the fathatan
-- BEFORE the alif throughout, which is what the 21-22 Sep native passes use (52/0 in the check's
-- anchor file, 84/1 in portalText.ts); 151 of the other order were normalised, changing no letter and
-- no meaning. And the non-response charge is رسوم عدم الاستجابة in every row — one answer had called
-- it رسوم عدم الرد, a second name for one fee. (messages/ar.json still carries 56 of the other tanwin
-- order; it is the website copy signed off on 14 Sep and is not touched here.)
--
-- IDEMPOTENT: each row is inserted only where no Arabic record already mirrors that English id, so a
-- re-apply adds nothing and a twin added by another file is never duplicated. 128 of the 130 rows
-- insert: ids 133 and 500 already have twins (that is the whole of the expected shortfall — measured
-- with the corrected id match, not the prefix match the first draft used).
--
-- AFTER APPLY (the coordinator, and this file is NOT done until it runs):
--   node scripts/kb/embed_sales_knowledge.mjs --table=company_faq
-- It selects every company_faq row whose embedding_gte is null, in ANY language, with no limit worth
-- worrying about (the default is 100,000), so ONE run covers both this file's 128 new Arabic rows and
-- the two ENGLISH rows (ids 1 and 10) whose vectors the licence correction nulls in
-- scripts/sql/the_licence_we_name_is_the_licence_we_hold.sql. Run it after BOTH files are applied.
--   — the free in-region gte-small, never OpenRouter. Until it runs these rows answer through the
--   keyword step only; the corroborated semantic step skips a record whose embedding_gte is null.
--
--   node scripts/apply_sql.mjs scripts/sql/the_arabic_faq_answers_every_question_the_english_one_does.sql --apply

insert into public.company_faq
  (section, sort, question, answer, audience, status, public, language, source_note, tags, approved_at, approved_by)
select 'Arabic', v.sort, v.question, v.answer, v.audience, 'approved', true, 'ar', v.note,
       array['arabic','mirror'], now(), 'customer_support'
  from (values
  (910, 'لماذا أُنشئت QuotesDone؟', 'أُنشئت QuotesDone لإصلاح طريقة الشراء في قطاع المقاولات والخدمات في الإمارات: الحصول اليوم على عدة عروض أسعار قابلة للمقارنة يعني ملاحقة الموردين واحدًا تلو الآخر، والإفصاح عن بيانات التواصل مسبقًا، ثم الردّ على المكالمات والمساومة — بينما يهدر الموردون وقتهم على أعمال ليست من اختصاصهم أصلًا. تتيح QuotesDone للمشتري وصف العمل مرة واحدة، وتلقّي عروض أسعار مجهولة الهوية وقابلة للمقارنة من موردين قادرين فعلًا، مع بقاء زمام الأمر بيده حتى يختار.', 'all', 'Arabic mirror of company_faq id 2', 2),
  (911, 'بماذا تختلف QuotesDone عن المنافسين؟', 'أربعة فوارق: (1) السرّية — لا يتبادل المشترون والموردون بيانات التواصل حتى يختار المشتري ويسدّد رسوم الاطلاع، فلا رسائل مزعجة ولا التفاف على المنصة. (2) مطابقة دقيقة عبر المحرّك الذكي — يقرأ المحرّك تفاصيل العمل فعليًا ويوجّهه إلى الموردين القادرين عليه وحدهم، بدل إرسال كل طلب إلى الجميع. (3) عروض أسعار منظَّمة وقابلة للمقارنة ومراجَعة الجودة، لا نصوصًا حرّة مبعثرة. (4) اقتصاديات منصفة للمورّد — لا عمولة على الأعمال المكتسبة والبداية مجانية؛ ولا يدفع المشتري إلا على العرض الذي يختاره فعلًا: رسوم اطلاع 3٪ إضافة إلى رسوم معالجة البطاقة.', 'all', 'Arabic mirror of company_faq id 9', 9),
  (912, 'هل يمكنني رفع المخططات؟', 'نعم — يمكنكم إضافة مخططات أو صور أو مقطع فيديو قصير. وتُنقّى المخططات تلقائيًا من أي تفاصيل تكشف الهوية قبل أن يطّلع عليها الموردون.', 'customer', 'Arabic mirror of company_faq id 20', 20),
  (913, 'هل يمكنني التفاوض؟', 'نعم — بعد اطّلاعكم على بيانات المورّد الذي اخترتموه، يمكنكم مناقشة النطاق والسعر والتوقيت معه مباشرة عبر المنصة. أما قبل الاطلاع فيبقى كل شيء مجهول الهوية، فتكتفون بمقارنة عروض الأسعار كما وردت.', 'customer', 'Arabic mirror of company_faq id 27', 27),
  (914, 'ما المستندات المطلوبة؟', 'الرخصة التجارية الإماراتية السارية هي المستند الأساسي. وسنطلب كذلك بيانات مساندة مثل شهادة ضريبة القيمة المضافة (الرقم الضريبي TRN)، والتأمين، وملف الشركة أو كتالوج المنتجات. واستمرار سريان الرخصة والتأمين يبقي حسابكم نشطًا.', 'supplier', 'Arabic mirror of company_faq id 37', 37),
  (915, 'ما المعلومات الإلزامية؟', 'عرض سعر كامل ومفصَّل بالبنود: نطاق العمل؛ بنود تفصيلية مع العلامة والطراز والمواصفات؛ الكميات وأسعار الوحدة؛ المواد؛ مدة التوريد؛ مدة سريان العرض؛ الضمان؛ شروط الدفع؛ وأي استثناءات. وعلى العرض أن يجتاز حدّ الجودة قبل وصوله إلى العميل — ويرشدكم المحرّك الذكي إذا نقص شيء مهم.', 'supplier', 'Arabic mirror of company_faq id 45', 45),
  (916, 'ماذا يحدث إذا لم أسدّد؟', 'إذا استحق اشتراككم السنوي (أو رسوم عدم الاستجابة) وبقي دون سداد، يُوقَف حسابكم عن استقبال المطابقات الجديدة إلى حين تسويته عبر البوابة. ونذكّركم قبل ذلك.', 'supplier', 'Arabic mirror of company_faq id 51', 51),
  (917, 'ما المقصود بطلب عرض السعر (RFQ)؟', 'RFQ اختصار لـ Request for Quotation، أي طلب عرض سعر — وهو طلب العمل الذي تقدّمونه. على QuotesDone تصفون ما تحتاجونه (كتابةً أو صوتًا أو بصورة أو مخطط)، فيحوّله المحرّك الذكي إلى موجز واحد واضح ومنظَّم يسعّر الموردون على أساسه.', 'all', 'Arabic mirror of company_faq id 59', 59),
  (918, 'هل يستطيع المحرّك الذكي تقدير المدد الزمنية؟', 'لا يَعِد المحرّك بتاريخ تسليم — فكل مورّد يذكر مدة توريده في عرضه. وكقاعدة عامة، تصل عروض الأسعار نفسها عادةً خلال 3-5 أيام عمل.', 'all', 'Arabic mirror of company_faq id 65', 65),
  (919, 'ما المستندات الواجب إرفاقها؟', 'المطلوب هو عرض السعر المفصَّل بالبنود نفسه. ويمكنكم اختياريًا إرفاق عرض سعر شركتكم الرسمي (PDF) — كما تُنشئ المنصة نسخة نظيفة مجهولة الهوية — ويُستحسن إرفاق صحائف البيانات الفنية للأصناف الخاضعة للتنظيم أو ذات العلامات التجارية. أما مستندات الشركة كالرخصة التجارية فتُقدَّم مرة واحدة عند التسجيل، لا مع كل عرض.', 'all', 'Arabic mirror of company_faq id 71', 71),
  (920, 'كيف تُحتسب درجات عروض الأسعار؟', 'يُقيَّم كل عرض بحسب مدى تغطيته للأقسام المطلوبة في فئته ومدى تفصيله بالبنود — نطاق العمل، والبنود مع العلامة والطراز والمواصفات، والكميات وأسعار الوحدة، والشروط التجارية. وعليه بلوغ حدّ الجودة كي يصبح قابلًا للإرسال إلى العميل.', 'all', 'Arabic mirror of company_faq id 77', 77),
  (921, 'أي المواد تناسب العمل؟', 'يعتمد ذلك على التطبيق. يستعين المحرّك الذكي بمعرفته بالمواد وبمواصفات الفئة ليضمن أن يستوعب موجزكم خيارات المواد المناسبة والعوامل التي تحرّك سعرها، وينبّه إلى المواضع التي يُستحسن أن يقترح فيها المورّد بدائل. وهو لا يفرض مادة بعينها — بل يضمن توثيق الخيار ومطابقته للاشتراطات.', 'all', 'Arabic mirror of company_faq id 83', 83),
  (922, 'كيف تعمل الفواتير؟', 'عندما يسدّد العميل رسوم الاطلاع، تصدر فاتورة بهذه الرسوم تلقائيًا وتتوفر داخل التطبيق. أما الموردون المُلزمون بالاشتراك السنوي (أي من هم خارج أول 1,000 مورّد مسجَّل) فتصلهم فاتورة به عند استحقاقه. وتصدر جميع الفواتير عن QuotesDone Technologies (راجعوا ملاحظة ضريبة القيمة المضافة أدناه بشأن المعاملة الضريبية الحالية).', 'all', 'Arabic mirror of company_faq id 91', 91),
  (923, 'ما مدى دقة المحرّك الذكي؟', 'صُمّم ليقدّم الدقة على التخمين: فإجاباته يجب أن تستند إلى مصادر مسترجَعة وموثَّقة (الأكواد الإماراتية ومعرفة الشركة)، وهو خاضع للقياس المرجعي والمراقبة. وعند عدم اليقين يصرّح بذلك أو يحيل الأمر بدل اختلاق إجابة. ولا نظام بلا نقص، ولهذا بُني على الاستناد إلى المصادر وعلى المراجعة والإشراف البشري.', 'all', 'Arabic mirror of company_faq id 100', 100),
  (924, 'كيف يتحسّن المحرّك الذكي باستمرار؟', 'يتحسّن ضمن ضوابط: تقيس المعايير المرجعية والتقييمات جودة تعليماته وإجاباته، ويراقب «المدرّب» جودة كل وكيل، وتُختبر التحسينات المقترحة قبل تفعيلها (ولا يُرقّى تلقائيًا إلا غير الحسّاس منها، ودائمًا مع إمكانية التراجع)، وتعود دروس الحالات المغلقة لتغذية معرفته.', 'all', 'Arabic mirror of company_faq id 106', 106),
  (925, 'ما الحد الأقصى لحجم الملف؟', 'لا يوجد حد صغير — يمكنكم رفع مخططات ومستندات كبيرة (حتى نحو 1 غيغابايت). والملفات الكبيرة جدًا تُرفَع أسرع بصيغة PDF أو بإرسال الصفحات الأساسية فقط، وهو ما يعطي أسرع تحليل كذلك.', 'all', 'Arabic mirror of company_faq id 123', 123),
  (926, 'كيف تُدار الفئات؟', 'تعتمد QuotesDone تصنيفًا للمهن، لكل مهنة دليل تأهيل خاص بها. وعندما يسجّل مورّد مهنة غير مدرجة لدينا بعد، يهيّئ المحرّك الذكي فئة جديدة تلقائيًا — الشخصية التعريفية وأسئلة الاستقبال ومعرفة الفئة — على أن يراجع شخصٌ المعرفة المولَّدة قبل بلوغها الجودة الكاملة.', 'all', 'Arabic mirror of company_faq id 130', 130),
  (927, 'ماذا يحدث عند إيقاف مورّد؟', 'يُستبعد المورّد الموقوف من المطابقة فورًا — فلا يوجّه إليه المحرّك الذكي أي طلبات عروض أسعار جديدة، ولا يستطيع تقديم عروض جديدة — من دون حذف أي شيء، ومع تسجيل السبب. والإيقاف (حجب المطابقة) قابل للرجوع عنه، أما الحظر الكامل فيُخرج المورّد من السوق. وكلاهما يخضع لمبدأ الإشراف أولًا: يرصد الوكلاء الخطر ويوصون، لكن الإجراء يُطبَّق بسلطة الإدارة لا تلقائيًا. أما ما التزم به المورّد سابقًا فيُعالَج حالة بحالة.', 'all', 'Arabic mirror of company_faq id 141', 141),
  (928, 'ماذا يحدث إذا تغيّرت الأنظمة؟', 'الأكواد الإماراتية واشتراطات الجهات محفوظة في قاعدة المعرفة، ويتابع «أمين المعرفة» المحتوى التنظيمي القديم أو الناقص. وعند تغيّر القواعد، تُستوعَب وثائق الجهات المحدَّثة وتُعتمد قبل تفعيلها وفق مبدأ الإشراف أولًا؛ ثم تُحدَّث اشتراطات الفئات وأدلة التأهيل ومعرفة الوكلاء. ويستدعي الوكلاء دائمًا الاشتراطات السارية ويرشدون المستخدمين إلى المصدر الرسمي المعتمد، فتبقى الإرشادات متوافقة مع أحدث الأنظمة.', 'all', 'Arabic mirror of company_faq id 147', 147),
  (929, 'سياسة انضمام العملاء', 'يسجّل العملاء بالتحقق من رقم الهاتف والبريد الإلكتروني ويقبلون الشروط والأحكام. ونشر الطلبات وتلقّي عروض الأسعار ومقارنتها مجاني؛ ولا يدفع العميل سوى رسوم الاطلاع 3٪ إضافة إلى رسوم معالجة البطاقة، على العرض الذي يختار فتحه. ويبقى العملاء مجهولين لدى الموردين حتى لحظة الاطلاع.', 'all', 'Arabic mirror of company_faq id 160', 160),
  (930, 'سياسة العمولة', 'لا تتقاضى QuotesDone أي عمولة من الموردين على الأعمال المكتسبة — إذ يحتفظ المورّد بـ100٪ من قيمة العمل. والمبالغ الوحيدة المحصَّلة من الموردين هي الاشتراك السنوي (1,000 درهم إماراتي سنويًا، ولا يسري إطلاقًا على أول 1,000 مورّد سجّلوا، ويطبَّق ابتداءً من التسجيل رقم 1,001 من دون تاريخ بدء محدَّد)، ورسوم عدم الاستجابة (وهي المبلغ المسترد للعميل بالضبط، أي رسوم الاطلاع 3٪ إضافة إلى رسوم معالجة البطاقة، زائد رسوم إدارية قدرها 250 درهمًا إماراتيًا وفائدة 9٪ سنويًا من تاريخ الاستحقاق) إذا تجاهل المورّد عميلًا سدّد رسوم الاطلاع عليه، وتُطبَّق إلا حيث لا يجيزها القانون الإماراتي. أما العميل فيدفع بصورة منفصلة رسوم اطلاع 3٪ إضافة إلى رسوم معالجة البطاقة، وذلك فقط عند اختياره الاطلاع على بيانات تواصل المورّد.', 'all', 'Arabic mirror of company_faq id 169', 169),
  (931, 'كيف سيتطوّر الذكاء الاصطناعي مستقبلًا؟', 'يتحسّن المحرّك الذكي باستمرار وبأمان: يُقيَّم الوكلاء ويُدرَّبون على نتائج واقعية، وتُنسَّق معرفتهم وتبقى محدَّثة وفق أحدث الأنظمة الإماراتية، ويمكن ترقية تعليماتهم ونماذجهم ومراجعتها والتراجع عنها ضمن حوكمة واضحة. ومع تحسّن نماذج الذكاء الاصطناعي الأساسية، تعتمدها QuotesDone حيث ترفع الدقة — لكن مبدأ الإشراف أولًا يبقى ثابتًا: قدرة أكبر، دائمًا تحت سيطرة بشرية، ودائمًا مستندة إلى معرفة موثَّقة لا إلى التخمين. والغاية قوة عمل من الذكاء الاصطناعي تزداد حدّة مع الوقت مع بقائها جديرة بالثقة.', 'all', 'Arabic mirror of company_faq id 175', 175),
  (932, 'ما المشكلة التي تحلّها QuotesDone؟', 'للمشترين: الحصول على عدة عروض أسعار موثوقة وقابلة للمقارنة بطيء وغير شفاف، وبمجرد انتشار رقمكم تبدأ رسائل الإلحاح والمتابعة. وللبائعين: معظم الفرص غير مناسبة أو سبق تداولها. QuotesDone تعالج الجانبين معًا: ينشر المشتري طلبه مرة واحدة، ويهيكل المحرّك الذكي الطلب ويوجّهه فقط إلى الموردين القادرين فعلًا على تنفيذه، فتعود عروض الأسعار مُهيكلة وقابلة للمقارنة وخاضعة لفحص الجودة، ويبقى كل شيء مجهول الهوية دون أي تواصل خارج المنصة إلى أن يسدّد المشتري رسوم الاطلاع على المورّد الذي اختاره.', 'all', 'Arabic mirror of company_faq id 3', 3),
  (933, 'ما الذي يجعل QuotesDone جديرة بالثقة؟', 'هي شركة مرخّصة في دبي (QuotesDone Technologies، رخصة تاجر رقم 1633275 – دائرة الاقتصاد والسياحة في دبي). والموردون يخضعون للتدقيق عبر فحص الرخصة ومتطلبات «اعرف عميلك». وتبقى بيانات المشتري والمورّد محجوبة إلى حين اطلاع مدفوع، بما يحمي الطرفين. وعروض الأسعار مُهيكلة وتمرّ ببوابة جودة ليقارن المشترون على أساس واحد. والمحرّك الذكي محكوم ومستند إلى معرفة موثَّقة للشركة وللأنظمة بدل التخمين، والإجراءات الحساسة مسجّلة وقابلة للتراجع، وتُعالَج البيانات وفق قانون حماية البيانات الشخصية الإماراتي مع ضوابط أمنية.', 'all', 'Arabic mirror of company_faq id 10', 10),
  (934, 'هل يمكنني رفع جداول الكميات؟', 'نعم، يمكنكم إرفاق جدول الكميات (BOQ)، ويستخدمه المحرّك الذكي في هيكلة طلبكم ليسعّر الموردون بنودكم بالتحديد.', 'customer', 'Arabic mirror of company_faq id 21', 21),
  (935, 'ماذا يحدث بعد اختيار المورّد؟', 'تسدّدون رسوم الاطلاع البالغة 3٪ إضافة إلى رسوم معالجة البطاقة، فتنكشف لكم هوية ذلك المورّد وبيانات التواصل معه. وتُنشأ معاملة، ويُخطَر المورّد ليردّ عليكم، وتواصلون العمل معه عبر المنصة.', 'customer', 'Arabic mirror of company_faq id 28', 28),
  (936, 'لماذا رُفض حسابي؟', 'نادرًا ما نرفض مورّدًا. لا يكتمل التسجيل قبل رفع المستندات المطلوبة في بوابة الموردين، لذا فالتسجيل الناقص يبقى غير مكتمل لا مرفوضًا. وإذا كان أحد المستندات غير صالح أو منتهي الصلاحية نطلب تحديثه، وبمجرد تصحيحه يمضي كل شيء كما ينبغي.', 'supplier', 'Arabic mirror of company_faq id 40', 40),
  (937, 'هل يمكنني تعديل عرض السعر بعد إرساله؟', 'لا، فعرض السعر نهائي بمجرد إرساله؛ لذا راجعوه بعناية قبل الإرسال. وبعد أن يطّلع العميل على هويتكم، لكم كامل الحرية في تعديل أي شيء معه مباشرة، فدور المنصة ينتهي عند تلك النقطة.', 'supplier', 'Arabic mirror of company_faq id 46', 46),
  (938, 'كيف يُحتسب تقييمي كمورّد؟', 'يعكس تقييمكم أداءكم الفعلي: تقييمات العملاء في التواصل والجودة والالتزام بالمواعيد والتوثيق وخدمة ما بعد البيع والامتثال، إضافة إلى سرعة استجابتكم وسجلّ النزاعات. وهو يبني سمعة موثوقة يراها العملاء.', 'supplier', 'Arabic mirror of company_faq id 52', 52),
  (939, 'ما المعلومات الإلزامية في طلب عرض السعر؟', 'ما يكفي المورّد لتقديم سعر ثابت دون الحاجة إلى التواصل معكم: ما تحتاجونه، والمواصفات والكميات الأساسية لهذا النوع من الأعمال، والمنطقة والإمارة بوجه عام، وأي مخططات أو جدول كميات لديكم. وتختلف الحقول الإلزامية بحسب الفئة، ويسألكم المحرّك الذكي عن أي معلومة ما زالت ناقصة.', 'all', 'Arabic mirror of company_faq id 60', 60),
  (940, 'هل يقترح المحرّك الذكي المواصفات؟', 'لا يفرض عليكم خيارات فنية. وحين يكون الخيار فنيًا يدوّنه على أنه «على المورّد اقتراح خيارات مناسبة مع أسعارها». ويستعين بمعرفة الفئة وبالأكواد الإماراتية ليضمن أن يغطي الطلب ما يهم وينبّه إلى متطلبات الامتثال، أما المواصفة الفنية فيقترحها المورّد ويسعّرها.', 'all', 'Arabic mirror of company_faq id 66', 66),
  (941, 'كيف تُقارَن عروض الأسعار؟', 'جنبًا إلى جنب ودون كشف الهوية (المورّد A وB وC)، وكلها موحّدة على الطلب نفسه لتكون المقارنة على أساس واحد. ويرى العميل سعر كل عرض وما يشمله وما يستثنيه ومدة التنفيذ والضمان والشروط، إلى جانب نطاق ثقة السعر للتحقق من القيمة.', 'all', 'Arabic mirror of company_faq id 72', 72),
  (942, 'هل يستطيع الموردون تعديل عروض الأسعار؟', 'لا، فعرض السعر نهائي بمجرد تقديمه؛ لذا ينبغي مراجعته بعناية قبل الإرسال. وبعد اطلاع العميل على هوية المورّد، تُرتَّب أي تعديلات بينهما مباشرة وخارج المقارنة.', 'all', 'Arabic mirror of company_faq id 78', 78),
  (943, 'ما الشهادات المطلوبة؟', 'تختلف بحسب النشاط والمنتج: مثلًا شهادات مطابقة المنتجات ECAS/EQM من MoIAT/ESMA للسلع الخاضعة للتنظيم، وترخيص SIRA لأعمال الأمن، وموافقات الدفاع المدني في دبي DCD لأنظمة الحريق، وتفويض الشركة المصنّعة لبعض المعدات ذات العلامات التجارية، إلى جانب الرخصة التجارية السارية للمورّد وتأمينه. والمحرّك الذكي ينبّه إلى الشهادات المرتبطة بعملكم.', 'all', 'Arabic mirror of company_faq id 84', 84),
  (944, 'كيف تُحصَّل العمولات؟', 'لا توجد عمولات، فالمورّد يحتفظ بـ100٪ من قيمة الأعمال التي يفوز بها. والمبالغ الوحيدة التي تُحصَّل من الموردين هي الاشتراك السنوي (1,000 درهم إماراتي سنويًا، ولا ينطبق أبدًا على أول 1,000 مورّد سجّلوا، وليس له تاريخ بدء محدد؛ فهو يسري اعتبارًا من التسجيل رقم 1,001)، ورسوم عدم الاستجابة إن وُجدت. ويُسدَّد كلاهما في بوابة الموردين عبر Stripe. وتُتابَع المبالغ غير المسددة، ويتوقف الحساب عن استقبال المطابقات الجديدة حتى تسويتها.', 'all', 'Arabic mirror of company_faq id 95', 95),
  (945, 'هل يخمّن المحرّك الذكي؟', 'لا، فهو مصمم على ألا يفعل. قاعدة استناد صارمة تُلزم بأن تأتي الإجابات من معرفة موثَّقة؛ وإذا لم تتوفر المعلومة يسألكم، أو يسجّل سؤالكم بندًا مفتوحًا لدى الوكيل المسؤول عنه، بدلًا من اختلاق مواصفات أو أسعار أو أنظمة.', 'all', 'Arabic mirror of company_faq id 101', 101),
  (946, 'كيف تُشفَّر البيانات؟', 'بياناتكم مشفّرة أثناء النقل، إذ يمر كل اتصال عبر TLS/HTTPS، ومشفّرة كذلك أثناء التخزين في قاعدة البيانات والتخزين السحابي المُدار لدينا. وتُعالَج مدفوعات البطاقات بالكامل لدى Stripe، فلا تمر بيانات البطاقة على خوادمنا إطلاقًا.', 'all', 'Arabic mirror of company_faq id 115', 115),
  (947, 'كيف تُحفَظ الملفات؟', 'في تخزين سحابي خاص محكوم الوصول وغير متاح للعامة. ولا تُعرض الملفات إلا على حسابكم أنتم عبر روابط موقّعة قصيرة الصلاحية.', 'all', 'Arabic mirror of company_faq id 124', 124),
  (948, 'كيف تُمنع ازدواجية الموردين؟', 'يُربَط كل مورّد بسجل شركة واحد يستند إلى رخصته التجارية وهوية الشركة، والدليل خالٍ من التكرار، فلا تظهر الشركة مرتين. وتُعلَّم التسجيلات المكررة أو المشبوهة للمراجعة.', 'all', 'Arabic mirror of company_faq id 131', 131),
  (949, 'ماذا يحدث عند انتهاء الرخصة؟', 'تواريخ انتهاء الرخص التجارية، ومعها التأمين وشهادات ISO وتفويضات المصنّعين، تخضع لمتابعة مستمرة. ومع اقتراب الانتهاء تصل التذكيرات ويُعلَّم البند في بطاقة امتثال المورّد. وبعد الانتهاء يُعامَل المورّد على أنه غير ممتثل ويبقى خارج المطابقة إلى أن يرفع تجديدًا ساريًا، وإعادة التوثيق تتطلب مستندات سارية. وهو إيقاف مؤقت لحين التجديد، لا حذف تلقائي.', 'all', 'Arabic mirror of company_faq id 142', 142),
  (950, 'ما بوابات الدفع المدعومة؟', 'تمر المدفوعات عبر Stripe، وهي تغطي المسارين الماليين: دفعة الاطلاع من العميل (رسوم الاطلاع 3٪ إضافة إلى رسوم معالجة البطاقة، لكشف بيانات التواصل مع المورّد) والاشتراك السنوي للمورّد (1,000 درهم إماراتي سنويًا). وتُطابَق إشعارات Stripe بحيث لا يُمنح الوصول إلا بعد تأكيد الدفع. ولا تتوفر بوابات أخرى في الوقت الحالي.', 'all', 'Arabic mirror of company_faq id 153', 153),
  (951, 'سياسة المستندات', 'تُرفع المستندات (الرخص والملفات التعريفية والكتالوجات والمخططات وعروض الأسعار والشروط الموقّعة) بحجم يصل إلى 1 غيغابايت إلى تخزين محكوم الوصول؛ وتُحفظ الملفات الكبيرة كاملة مع تلخيص تلقائي منها للمحرّك الذكي. ولا تُفتح الملفات إلا عبر روابط موقّعة قصيرة الصلاحية وللمخوَّلين وحدهم، ولا يرى أي طرف مستندات الطرف الآخر الخاصة.', 'all', 'Arabic mirror of company_faq id 161', 161),
  (952, 'سياسة الجودة', 'يجب أن تكون عروض الأسعار مفصّلة بالبنود لا تقديرات إجمالية، ليقارن العملاء على أساس واحد ولتكشف المقارنة التكاليف المخفية واستبدال المواصفات بأدنى منها والبنود الناقصة. والموردون يخضعون للتدقيق ويُقيَّمون على الاستحقاق، والوكلاء مستندون إلى معرفة معتمدة ويخضعون لتدريب مستمر. والمبدأ الحاكم في ذلك كله هو الدقة قبل الكم.', 'all', 'Arabic mirror of company_faq id 170', 170),
  (953, 'هل هناك رسوم اشتراك على الموردين؟', 'لا رسوم على أول 1,000 مورّد يسجّلون، ولا في أي وقت لاحق. فالتسجيل مجاني لأول 1,000 مورّد مسجّل، وإعفاؤهم دائم. أما كل مورّد يسجّل بعدهم فيدفع اشتراكًا سنويًا قدره 1,000 درهم إماراتي في السنة؛ ولا يوجد تاريخ بدء محدد، إذ يسري اعتبارًا من التسجيل رقم 1,001. ولا توجد أي عمولة على الأعمال التي تفوزون بها.', 'all', 'Arabic mirror of company_faq id 500', 500),
  (954, 'لمن تُقدَّم خدمة QuotesDone؟', 'طرفان. العملاء (المشترون) — شركات وأفراد في الإمارات يحتاجون إلى شراء منتجات أو خدمات البناء والتشطيبات والأعمال الكهروميكانيكية وما يتصل بها، ويريدون عروض أسعار سريعة وقابلة للمقارنة دون التعرّض للرسائل المزعجة. الموردون (البائعون) — مقاولون ومصنّعون وأصحاب حرف وموردون موثَّقون في الإمارات يريدون طلبات عمل مؤهَّلة وذات صلة يستطيعون تسعيرها.', 'all', 'Arabic mirror of company_faq id 4', 4),
  (955, 'كيف يُختار الموردون؟', 'يقرأ المحرك الذكي طلبكم الفعلي ويطابقه وفق القدرة الحقيقية والموقع، فلا يدعو إلا الموردين القادرين فعلًا على تنفيذه. والمطابقة الخاطئة أسوأ من عدم المطابقة، ولذلك يُستبعد الموردون غير المناسبين.', 'customer', 'Arabic mirror of company_faq id 14', 14),
  (956, 'هل أستطيع دعوة مورّد من عندي؟', 'لا — لا يستطيع العملاء دعوة موردين من طرفهم. تتولى QuotesDone البحث عن الموردين والتحقق منهم نيابةً عنكم، وهو ما يبقي كل عرض سعر مجهول الهوية وعادلًا ومدقَّق الجودة.', 'customer', 'Arabic mirror of company_faq id 22', 22),
  (957, 'ماذا لو اختفى المورّد؟', 'إذا لم يردّ المورّد الذي اطّلعتم على بياناته خلال 5 أيام عمل من سدادكم (نتابعه بعد 3 أيام عمل، ونتخذ القرار النهائي في اليوم الخامس)، يُردّ إليكم كل ما دفعتموه. ويصبح ذلك المورّد مدينًا بالمبلغ المردود نفسه (رسوم الاطلاع 3٪ إضافة إلى رسوم معالجة البطاقة)، ورسوم إدارية قدرها 250 درهمًا إماراتيًا، وفائدة بسيطة بنسبة 9٪ سنويًا (أو الحد الأقصى المسموح به قانونًا) من تاريخ الاستحقاق، ويُحجب عن المطابقات الجديدة حتى السداد.', 'customer', 'Arabic mirror of company_faq id 32', 32),
  (958, 'كيف تُسنَد المشاريع؟', 'يقرأ المحرك الذكي كل طلب من العميل ويطابقه مع الموردين القادرين فعلًا على تنفيذه، استنادًا إلى قدراتكم الحقيقية والإمارات التي تخدمونها. ولا يُدعى سوى الموردين المؤهلين فعليًا، فلن تصلكم طلبات لا علاقة لكم بها.', 'supplier', 'Arabic mirror of company_faq id 41', 41),
  (959, 'هل أستطيع سحب عرض سعر؟', 'نعم — يمكنكم سحب عرض السعر قبل أن يطّلع عليه العميل.', 'supplier', 'Arabic mirror of company_faq id 47', 47),
  (960, 'كيف أُحسّن ترتيبي؟', 'ردّوا بسرعة، وقدّموا عروض أسعار كاملة ومفصّلة بالبنود، ونفّذوا العمل بإتقان لتنالوا تقييمات قوية، وحافظوا على سريان رخصتكم ومستنداتكم وعلى التزامكم بالمتطلبات. الترتيب يقوم على الاستحقاق لا على الدفع.', 'supplier', 'Arabic mirror of company_faq id 53', 53),
  (961, 'كيف يؤهّل المحرك الذكي طلب عرض السعر؟', 'يقرأ كلماتكم وصوركم أو مخططاتكم، ويحوّلها إلى موجز جاهز للموردين، ويطبّق دليل تأهيل الفئة المعنية ليطرح الأسئلة الصحيحة، ويقيس مدى اكتمال الطلب — ولا يرسله إلا حين يصبح جاهزًا للتسعير.', 'all', 'Arabic mirror of company_faq id 61', 61),
  (962, 'كيف يُطابَق الموردون بطلب عرض السعر؟', 'يضع المحرك الذكي قائمة مختصرة بالموردين وفق القدرة الحقيقية والكلمات المفتاحية والإمارات التي يخدمونها، ثم يقيّم كل مرشّح بما إذا كان قادرًا فعلًا على تنفيذ عملكم بالتحديد. ولا يُدعى سوى الموردين المؤهلين فعليًا — فالمطابقة الخاطئة أسوأ من عدم المطابقة — مع سقف لعددهم حفاظًا على جدوى العروض.', 'all', 'Arabic mirror of company_faq id 67', 67),
  (963, 'ما هو جدول الكميات (BOQ)؟', 'جدول الكميات هو القائمة التفصيلية للمواد والأعمال — لكل بند كميته ووحدته — التي يُسعَّر عرض السعر على أساسها. وهو ما يجعل العروض دقيقة وقابلة للمقارنة مباشرة.', 'all', 'Arabic mirror of company_faq id 73', 73),
  (964, 'ما اللوائح المنطبقة؟', 'يعتمد ذلك على التخصص والإمارة. يستند المحرك الذكي إلى مكتبة تنظيمية إماراتية مفهرسة، ويحدّد الأكواد ذات الصلة بعملكم تحديدًا — مثل هيئة كهرباء ومياه دبي (DEWA) للأعمال الكهربائية، والدفاع المدني بدبي (كود الإمارات للحماية من الحريق والسلامة) لأعمال الحريق، وبلدية دبي (السعفات للمباني الخضراء، والصرف) للمباني، وسيرا (SIRA) للأمن وكاميرات المراقبة، ووزارة الصناعة والتكنولوجيا المتقدمة وهيئة الإمارات للمواصفات والمقاييس (ECAS) للمنتجات، وتراخيص (Trakhees) وسلطة دبي للتطوير (DDA) داخل المناطق الحرة. ويبقى المورّد مسؤولًا عن التصميم المطابق للأكواد وعن الحصول على موافقات الجهات المختصة.', 'all', 'Arabic mirror of company_faq id 79', 79),
  (965, 'ما الضمانات المقبولة؟', 'لا توجد قاعدة واحدة ثابتة — فالضمان حقل إلزامي في كل عرض سعر، ولذلك يُذكر دائمًا ويسهل مقارنته. والممارسة المعتادة في الإمارات (مثل ضمان جودة التنفيذ إلى جانب ضمان الشركة المصنّعة للمنتج) مرصودة لكل فئة، وأنتم تقرّرون ما يناسب عملكم.', 'all', 'Arabic mirror of company_faq id 85', 85),
  (966, 'كيف تُعالَج المبالغ المتأخرة؟', 'نرسل تذكيرات أولًا. وإذا بقي مبلغ مستحق — اشتراك مورّد أو رسوم عدم استجابة — دون سداد، يتوقف الحساب عن استقبال المطابقات الجديدة حتى تسوية المبلغ عبر البوابة.', 'all', 'Arabic mirror of company_faq id 96', 96),
  (967, 'كيف يستفيد المحرك الذكي من المعرفة؟', 'يسترجع من قاعدة معرفة منسّقة — اللوائح والمواصفات الإماراتية، وخبرة الفئات، والمواد، ومعلومات الشركة — ويؤسّس إجاباته على تلك المصادر. والمعرفة خاضعة لضبط الإصدارات وتُراجَع قبل اعتمادها.', 'all', 'Arabic mirror of company_faq id 102', 102),
  (968, 'كيف تُحمى المستندات؟', 'تُحفظ الملفات كالرخص والمخططات وعروض الأسعار في تخزين خاص غير متاح للعموم، ولا يُوصل إليها إلا من داخل التطبيق عبر روابط موقَّعة قصيرة الصلاحية، وتُفحص الملفات المرفوعة بحثًا عن البرمجيات الخبيثة، كما تُحجب تلقائيًا التفاصيل التعريفية من مخططات العميل قبل أن يراها أي مورّد.', 'all', 'Arabic mirror of company_faq id 116', 116),
  (969, 'كيف تُدار الإصدارات؟', 'تخضع المستندات لضبط الإصدارات — فأي تحديث ينشئ إصدارًا جديدًا بدل محو السجل، بما يتيح تتبّعًا موثَّقًا. كما تُحفظ طلبات عروض الأسعار بإصدارات عند تعديلها.', 'all', 'Arabic mirror of company_faq id 125', 125),
  (970, 'كيف يُكشف الاحتيال؟', 'عبر فحص آلي للاحتيال وتدقيق للحالات الشاذة، ورصد تسريب بيانات التواصل في المحادثة داخل المنصة، ومصائد تحذيرية، وتدقيق المستندات — مع وضع علامة على الحسابات المشبوهة وحجبها عن المطابقة عند الاقتضاء. كما أن نموذج إخفاء الهوية بحد ذاته يزيل معظم الدافع للتحايل.', 'all', 'Arabic mirror of company_faq id 132', 132),
  (971, 'ماذا يحدث إذا فشل الدفع؟', 'تمرّ المدفوعات عبر Stripe. إذا فشل سداد العميل لرسوم الاطلاع (3٪ إضافة إلى رسوم معالجة البطاقة، لكشف بيانات التواصل مع المورّد)، فلا تُكشف البيانات ويمكن إعادة المحاولة — دون أي خصم ودون كشف أي هوية. وإذا فشل سداد الاشتراك السنوي للمورّد (1,000 درهم إماراتي سنويًا)، لا يُفعَّل تسجيله أو ينتهي سريانه، فتتوقف المطابقات الجديدة حتى السداد. والدفع الفاشل لا يمنح صلاحية وصول بصمت أبدًا؛ وتُطابَق أحداث Stripe مع السجلات لتبقى دقيقة.', 'all', 'Arabic mirror of company_faq id 143', 143),
  (972, 'هل يستطيع الموردون ربط أنظمة تخطيط الموارد (ERP)؟', 'ليس في هذه المرحلة. يعمل الموردون عبر بوابة QuotesDone — التسجيل، واستقبال طلبات عروض الأسعار المطابقة، وتقديم عروض مفصّلة بالبنود فيها. ولا يوجد اليوم رابط مباشر مع أنظمة ERP (مثل SAP أو Oracle أو Odoo). وقد يُدرَج ربط ERP بخارطة الطريق إذا زاد الطلب، لكنه غير متاح حاليًا.', 'all', 'Arabic mirror of company_faq id 155', 155),
  (973, 'سياسة الخصوصية', 'تبقى هويات العملاء والموردين محجوبة (يظهر الموردون للعميل بالرموز A/B/C، ويبقى العميل مجهولًا لدى الموردين) إلى حين إتمام اطّلاع مدفوع. ولا تُستخدم البيانات الشخصية إلا لتشغيل السوق، ولا تُباع إطلاقًا، وتُعالَج وفق قانون حماية البيانات الشخصية الإماراتي مع منح أقل صلاحية ممكنة. وطلبات أصحاب البيانات بالاطلاع عليها ومحوها مدعومة.', 'all', 'Arabic mirror of company_faq id 162', 162),
  (974, 'لماذا تبني QuotesDone موظفين بالذكاء الاصطناعي؟', 'بُنيت QuotesDone على مبدأ الذكاء الاصطناعي أولًا: فبدل التوسّع بزيادة عدد الموظفين، تعمل بفريق من وكلاء المحرك الذكي — للمطابقة، ونجاح الموردين والعملاء، والمالية، والتسويق، والمعرفة، والشؤون القانونية، والأمن، والعمليات. ويتيح ذلك لشركة إماراتية صغيرة الحجم أن تقدّم خدمة بمستوى المؤسسات على مدار الساعة — أسرع وأكثر اتساقًا ومستندة إلى معرفة موثَّقة. والوكلاء يعملون تحت إشراف دائم: يعرضون ويوصون ويصعّدون، بينما يعتمد إنسان كل ما هو حساس أو غير قابل للتراجع. الهدف هو الرافعة والجودة، لا استبدال الحكم البشري.', 'all', 'Arabic mirror of company_faq id 171', 171),
  (975, 'ما المستندات التي يحتاجها المورّد للتوثيق؟', 'يلزم ستة أمور لاستكمال تسجيل المورّد: اسم الشركة، ورقم هاتف متحرك، وبريد إلكتروني، والرخصة التجارية، وملف تعريفي للشركة، وقبولكم الموقَّع لشروط الموردين. هذه هي المجموعة الإلزامية كاملةً — وبمجرد استيفائها تصبحون موثَّقين ويمكنكم البدء باستقبال الطلبات.

وما عدا ذلك اختياري ولا يزيد ملفكم إلا قوة: شهادة ضريبة القيمة المضافة، وتأمين المهنة أو المسؤولية، وشهادات الأيزو، وتفويضات الشركات المصنّعة، وتفاصيل المعدات والفريق، ومراجع العملاء. ولا يعطّل أيٌّ منها تسجيلكم، ويمكنكم إضافتها في أي وقت من بوابة الموردين.', 'supplier', 'Arabic mirror of company_faq id 623', 623),
  (976, 'في أي دول تعمل QuotesDone؟', 'تعمل QuotesDone حاليًا في دولة الإمارات العربية المتحدة، في الإمارات السبع جميعها، ومقرها دبي. أما التوسّع إلى المملكة العربية السعودية فمُخطَّط له ولم ينطلق بعد.', 'all', 'Arabic mirror of company_faq id 6', 6),
  (977, 'هل يمكنني اختيار الموردين الذين يصلهم طلبي؟', 'يتولّى المحرّك الذكي اختيار الموردين المناسبين لكم؛ فهذا يحفظ عدالة العملية وسرعتها وسريّتها الكاملة، ولا حاجة لانتقاء الموردين يدويًا من دليل.', 'customer', 'Arabic mirror of company_faq id 15', 15),
  (978, 'هل يمكنني طلب تعديل عرض السعر؟', 'لا تعديل على عروض الأسعار. تقارنون العروض كما وردت، وإن لم يناسبكم أي منها فلكم رفضها جميعًا دون أي تكلفة ونشر طلب أوضح. وبعد اطّلاعكم على بيانات المورّد الذي اخترتموه، تتّفقون معه مباشرة على أي تغييرات عبر المنصّة.', 'customer', 'Arabic mirror of company_faq id 23', 23),
  (979, 'ماذا لو وصلتني عروض أسعار ضعيفة؟', 'كل عرض سعر يجتاز حدًّا أدنى للجودة قبل أن يصلكم، والمحرّك الذكي يوجّه الموردين إلى عروض كاملة ومفصّلة ببنودها. وإن بقيتم غير راضين، فلكم رفضها جميعًا دون أي تكلفة؛ فالدفع لا يكون إلا عند اختياركم الاطّلاع على بيانات مورّد.', 'customer', 'Arabic mirror of company_faq id 33', 33),
  (980, 'هل يمكنني رفض الدعوات؟', 'نعم، لكم أن تتجاهلوا أي دعوة لا تناسبكم، ولا غرامة على عدم تقديم عرض سعر. (الرسم الوحيد يترتّب إذا سدّد عميل رسوم الاطلاع على بياناتكم ثم تجاهلتموه.)', 'supplier', 'Arabic mirror of company_faq id 42', 42),
  (981, 'متى أعرف أنني فزت بالطلب؟', 'يصلكم إشعار فور سداد العميل رسوم الاطلاع على عرضكم؛ وهذه إشارتكم للردّ والمضي في التنفيذ. وإن اختار العميل مورّدًا آخر نُعلمكم بذلك أيضًا، فلا تبقون في انتظار.', 'supplier', 'Arabic mirror of company_faq id 48', 48),
  (982, 'هل يمكنني الإعلان على المنصّة؟', 'لا إعلانات على QuotesDone. بدلًا من ذلك ينال كل مورّد تقييمًا وفق معايير QuotesDone استنادًا إلى أدائه الفعلي؛ فتتميّزون بحسن التنفيذ لا بالدفع.', 'supplier', 'Arabic mirror of company_faq id 54', 54),
  (983, 'ما الذي يجعل طلب عرض السعر مكتملًا؟', 'يكتمل الطلب حين يتضمّن كل ما يحتاجه المورّد لتقديم سعر ثابت دون لقائكم: نطاق عمل واضح، والمواصفات والكميات المؤثّرة في السعر لتلك الفئة، والمنطقة والإمارة، وأي صور أو مخططات لازمة. عندها يُعتمد الطلب جاهزًا ويذهب إلى الموردين المطابقين.', 'all', 'Arabic mirror of company_faq id 62', 62),
  (984, 'كيف تُقاس جودة طلب عرض السعر؟', 'يُقيَّم كل طلب من حيث اكتماله وفق قائمة تحقّق الفئة ودليل عملها، وعليه بلوغ حدّ «جاهز» قبل إرساله إلى الموردين. (وبشكل منفصل، تخضع عروض الموردين بدورها لبوابة جودة، فتكون المقارنة بين عروض كاملة ومتكافئة.)', 'all', 'Arabic mirror of company_faq id 68', 68),
  (985, 'ما الذي تشمله المقارنة؟', 'لكل عرض سعر: السعر، والبنود التفصيلية، ونطاق العمل وما يشمله وما يستثنيه، ومدة التنفيذ، وصلاحية العرض، والضمان، وشروط الدفع، إضافة إلى تقييم المورّد وحالة توثيقه ونطاق ثقة السعر. أي كل ما يحتاجه العميل ليختار على أساس القيمة لا على أساس أقل رقم.', 'all', 'Arabic mirror of company_faq id 74', 74),
  (986, 'ما المعايير المعتمدة؟', 'المواصفات الوطنية UAE.S / GSO، إضافة إلى المعايير الدولية التي يحيل إليها الكود الإماراتي حيث تنطبق على المهنة، مثل ISO وEN، وIEC / BS 7671 للتمديدات الكهربائية، وASHRAE للتكييف، وNFPA للحريق. ويُبرز المحرّك الذكي المعايير المتّصلة بفئتكم بدل قائمة واحدة شاملة.', 'all', 'Arabic mirror of company_faq id 80', 80),
  (987, 'ما الاختبارات المطلوبة؟', 'يعتمد ذلك على النظام؛ فمثلًا اختبار الضغط للسباكة، واختبارات مقاومة العزل والتأريض للكهرباء (ديوا)، والاختبار والتشغيل التجريبي لأنظمة الحريق (الدفاع المدني/NFPA)، واختبار الإغراق للعزل المائي. ويحرص المحرّك الذكي على إدراج الاختبار والتشغيل التجريبي ضمن نطاق العمل حيثما لزم، ويتولّى المورّد تنفيذها واعتمادها.', 'all', 'Arabic mirror of company_faq id 86', 86),
  (988, 'ماذا يفعل المحرّك الذكي؟', 'يدير QuotesDone من أولها إلى آخرها: يفهم طلب العميل ويحوّله إلى وصف واضح، ويطابقه مع موردين قادرين فعلًا، ويتحقّق من جودة عروض الأسعار، ويجيب عن الأسئلة استنادًا إلى معرفة إماراتية موثَّقة، ويدير العمليات اليومية، مستندًا دائمًا إلى بيانات حقيقية، دون اختلاق أسعار أو علامات تجارية أو قواعد.', 'all', 'Arabic mirror of company_faq id 97', 97),
  (989, 'متى يحيل المحرّك الذكي الأمر إلى إنسان؟', 'كلما كان الإجراء حسّاسًا أو غير قابل للتراجع أو منخفض الثقة أو خارج السياسة — كالأموال، ونشر الشؤون القانونية والعقود، وتغييرات التسعير أو السياسات، والامتثال عالي المخاطر — يتوقّف ويحيله إلى موافقة بشرية، مرفقًا بكامل السياق وبتوصيته.', 'all', 'Arabic mirror of company_faq id 103', 103),
  (990, 'من يستطيع الاطّلاع على ملفاتي؟', 'أنتم والأطراف المخوّلة فقط. تعرض المنصّة ملفاتكم على حسابكم وحده، وتبقى هويّة كلٍّ من العميل والمورّد محجوبة عن الآخر حتى الاطلاع المدفوع. ولا وجود لأي وصول عام أو مفتوح إلى الملفات؛ فكل ملف يُقدَّم عبر الأنظمة الخلفية بتخويل صارم.', 'all', 'Arabic mirror of company_faq id 117', 117),
  (991, 'كيف تُعالَج المخططات؟', 'عند رفعكم مخططًا، يقرأه المحرّك الذكي ليصوغ جدول كميات ويبني وصف طلبكم، ويحجب تلقائيًا التفاصيل التي تكشف هويّتكم قبل أن يراه أي مورّد، فتبقون مجهولين. أما ملفاتكم الأصلية فتظلّ خاصة بكم.', 'all', 'Arabic mirror of company_faq id 126', 126),
  (992, 'كيف تُدار النزاعات؟', 'تسير النزاعات وفق مسار محدّد: ترفعون المشكلة، فتُراجَع بكامل سجلّها، وتُحلّ عبر المنصّة، بما في ذلك ردّ المبالغ عند الاقتضاء، وتُسوّى مقابل المعاملة الأصلية. والغاية نتيجة منصفة للطرفين.', 'all', 'Arabic mirror of company_faq id 133', 133),
  (993, 'ماذا يحدث عندما تكون ثقة الذكاء الاصطناعي منخفضة؟', 'انخفاض الثقة يستدعي التحفّظ لا الإقدام. ففي المطابقة القاعدة أن «المطابقة الخاطئة أسوأ من عدمها»؛ فإن لم يكن المحرّك واثقًا من ملاءمة مورّد فعلًا استبعده، وقد يعيد صفر نتائج بدل التخمين. وفي ما عدا ذلك — كأوصاف القدرات، ومعرفة الفئات الجديدة، وقراءة المستندات — يُوسَم المخرَج منخفض الثقة ويُحتجز لمراجعة بشرية قبل نشره أو العمل به. فهو يحيل الأمر إلى إنسان بدل المضي فيه.', 'all', 'Arabic mirror of company_faq id 144', 144),
  (994, 'هل يمكن للعملاء ربط أنظمة المشتريات لديهم؟', 'ليس حاليًا. ينشر العملاء طلبات عروض الأسعار ويستقبلون العروض عبر تطبيق QuotesDone، ولا يوجد حتى الآن ربط punch-out أو موصّل للمشتريات الإلكترونية (مثل Ariba أو Coupa أو Oracle Procurement). وهي إضافة ممكنة مستقبلًا، لكنها غير متاحة اليوم.', 'all', 'Arabic mirror of company_faq id 156', 156),
  (995, 'سياسة الاحتفاظ بالبيانات', 'تُحفظ السجلات والمستندات التشغيلية ما دام الحساب نشطًا، وللمدة اللازمة لتشغيل السوق والوفاء بالالتزامات القانونية والضريبية والمتعلّقة بالنزاعات. وتُلبّى طلبات المحو وفق قانون حماية البيانات الشخصية، مع مراعاة أي حجز قانوني. ولا يحذف الوكلاء البيانات حذفًا نهائيًا؛ فالإزالة إجراء منضبط يقرّه إنسان.', 'all', 'Arabic mirror of company_faq id 163', 163),
  (996, 'ما خارطة الطريق على المدى البعيد؟', 'التركيز القريب هو العمق في سوق الأعمال الإماراتي: مطابقة أدقّ، وموردون أكثر بقدرات موثَّقة وغنيّة، وتحسين مستمر لجودة عروض الأسعار ومقارنتها. وبعد ذلك يتّجه العمل إلى تغطية فئات أوسع، وأدوات أعمق للموردين والعملاء، وتحليلات أقوى، ومع نمو الطلب: عمليات ربط (مثل أنظمة تخطيط الموارد والمشتريات) وربما واجهة برمجية للشركاء. وتمضي بنود خارطة الطريق بتأنٍّ ولا تُطلق إلا عند جاهزيتها الفعلية؛ ونفضّل الوعد بالأقل والتقديم بالأكثر.', 'all', 'Arabic mirror of company_faq id 172', 172),
  (997, 'هل يغطّي المورّد في دبي إمارة أبوظبي أيضًا؟', 'يعتمد ذلك على المورّد، ولا داعي للتخمين. فعند نشر طلبكم تحدّدون موقع العمل، ويصل هذا الموقع إلى الموردين مع الطلب؛ فمن لا يخدم تلك الإمارة ببساطة لا يقدّم عرضًا. وكل عرض سعر يصلكم هو من جهة اختارت التقدّم وهي تعرف موقع العمل.

وكثير من المقاولين المرخّصين في دبي ينفّذون أعمالًا في مختلف الإمارات، وبعضهم يسعّر الانتقال أو التعبئة بشكل منفصل للأعمال خارج إمارة مقرّه. اطلبوا منهم تأكيد نطاق التغطية وأي تكلفة انتقال أو دخول للموقع مباشرة بعد اطّلاعكم على بيانات التواصل وقبل الالتزام؛ فتلك هي اللحظة التي تتحدّثون فيها معهم ويمكن تثبيت ذلك كتابةً.', 'customer', 'Arabic mirror of company_faq id 624', 624),
  (998, 'ما رؤية الشركة على المدى الطويل؟', 'أن تصبح QuotesDone طبقة المشتريات الموثوقة في المنطقة، والوسيلة المعتمدة لطلب عروض الأسعار ومقارنتها في دول الخليج، مع التوسّع من الإمارات إلى المملكة العربية السعودية وما بعدها، والانتقال من طلبات العمل الواحد إلى مشتريات يدعمها المحرك الذكي لمشاريع أكبر ومتعددة التخصصات.', 'all', 'Arabic mirror of company_faq id 7', 7),
  (999, 'هل يمكنني إلغاء الطلب؟', 'نعم، يوجد زر إلغاء يتيح لكم إلغاء طلبكم قبل الاطلاع على أي مورّد، ودون أي تكلفة؛ فالدفع لا يستحق إلا عند خطوة الاطلاع. ونحتفظ بسجل لعمليات الإلغاء، وإذا صار الإلغاء عادة متكررة أرسلنا إليكم رسالة مهذبة توضّح أن تكرار الإلغاء يؤثر على الموردين الذين يبذلون وقتًا في إعداد عروضهم.', 'customer', 'Arabic mirror of company_faq id 18', 18),
  (1000, 'هل يمكنني رفض جميع عروض الأسعار؟', 'نعم، لستم ملزمين بقبول أي عرض سعر. والدفع لا يستحق إلا عند اختياركم الاطلاع على مورّد، لذا فإن رفض جميع العروض لا يكلّفكم شيئًا.', 'customer', 'Arabic mirror of company_faq id 24', 24),
  (1001, 'ماذا لو وقع خطأ في طلبي؟', 'يمكنكم تعديل الطلب خلال ساعة واحدة من إرساله لتصحيح الخطأ. وبعد انقضاء هذه المهلة، ألغوا الطلب وأنشئوا طلبًا مصحّحًا؛ فالإلغاء قبل الاطلاع لا يكلّف شيئًا.', 'customer', 'Arabic mirror of company_faq id 34', 34),
  (1002, 'كم عدد الموردين الذين يصلهم طلب عرض السعر نفسه؟', 'عدد محدود فقط من الموردين القادرين فعليًا على تنفيذ العمل؛ فالعدد مقيّد للحفاظ على منافسة عادلة ولإبقاء كل دعوة ذات صلة، وليس إرسالًا جماعيًا.', 'supplier', 'Arabic mirror of company_faq id 43', 43),
  (1003, 'كيف تُحتسب العمولات؟', 'لا توجد عمولة على الأعمال التي تفوزون بها؛ فتحتفظون بقيمة العمل كاملةً 100٪. والرسم الوحيد المرتبط بعمل ما هو رسم عدم الاستجابة إذا تجاهلتم عميلًا سدّد رسوم الاطلاع عليكم: المبلغ المعاد إلى العميل بالضبط (رسوم الاطلاع 3٪ مع رسوم معالجة البطاقة المحتسبة عليها)، ورسم إداري قدره 250 درهمًا إماراتيًا، وفائدة بسيطة بنسبة 9٪ سنويًا (أو الحد الأقصى المسموح به قانونًا) اعتبارًا من تاريخ الاستحقاق.', 'supplier', 'Arabic mirror of company_faq id 49', 49),
  (1004, 'هل يمكنني العمل في أكثر من إمارة؟', 'نعم، تحدّدون الإمارات التي تخدمونها، وتُطابَقون مع الأعمال في كل واحدة منها.', 'supplier', 'Arabic mirror of company_faq id 55', 55),
  (1005, 'ماذا يحدث إذا كانت هناك معلومات ناقصة؟', 'يطرح المحرك الذكي بضعة أسئلة سهلة تُجاب بنقرة واحدة لسدّ الفجوات. وإذا كان أمر ما غير معروف فعلًا، سُجّل بندًا مفتوحًا يقترح المورّد حلّه، فلا تتوقفون عند أي نقطة، ولا يخرج الطلب إلى الموردين إلا بعد اكتماله بالقدر الكافي للتسعير.', 'all', 'Arabic mirror of company_faq id 63', 63),
  (1006, 'ما الذي يميّز عرض السعر الجيد؟', 'عرض كامل ومفصّل بأسعار واضحة: بنود تحمل العلامة والطراز والمواصفات والكميات وأسعار الوحدات، إضافة إلى نطاق العمل والمواد ومدة التوريد وصلاحية العرض والضمان وشروط الدفع وأي استثناءات. والعروض الجيدة أسهل على العميل في المقارنة، وتفوز أكثر.', 'all', 'Arabic mirror of company_faq id 69', 69),
  (1007, 'ماذا يحدث إذا كان عرض السعر ناقص المعلومات؟', 'يجب أن تجتاز العروض حدًّا أدنى من الجودة قبل أن يراها العميل. وإذا نقص أمر مهم، أرشد المحرك الذكي المورّد إلى استكماله، وبقي العرض مسوّدةً حتى يستوفي المعيار، فلا يقارن العملاء إلا عروضًا مكتملة.', 'all', 'Arabic mirror of company_faq id 75', 75),
  (1008, 'ما الشركات المصنّعة المعتمدة؟', 'لا تضع QuotesDone قائمة مصنّعين معتمدين لديها ولا تزكّي شركات بعينها. المهم أن تستوفي المنتجات المعروضة الاعتمادات المطلوبة في الإمارات لطبيعة العمل، مثل منتجات الحريق المدرجة لدى الدفاع المدني، والمنتجات الخاضعة للتنظيم المطابقة لمواصفات ESMA/ECAS، أو المعدات الكهربائية المعتمدة من هيئة كهرباء ومياه دبي. ويستند المحرك الذكي إلى اعتمادات الجهات المعترف بها، والمورّد هو من يقترح المنتجات المطابقة.', 'all', 'Arabic mirror of company_faq id 81', 81),
  (1009, 'ما عمليات التفتيش المطلوبة؟', 'تختلف عمليات تفتيش الجهات بحسب التخصص، مثل تفتيش الحريق من الدفاع المدني في دبي قبل الإشغال، وتفتيش هيئة كهرباء ومياه دبي وتوصيل التيار في الأعمال الكهربائية، وتفتيش بلدية دبي لأعمال البناء، وتفتيش تراخيص وسلطة دبي للتطوير داخل المناطق الحرة. ويحدّد المحرك الذكي عمليات التفتيش المتعلقة بعملكم، ويتولّى المورّد أو الاستشاري تنسيقها.', 'all', 'Arabic mirror of company_faq id 87', 87),
  (1010, 'ما القرارات التي يستطيع المحرك الذكي اتخاذها؟', 'القرارات منخفضة المخاطر، القابلة للتراجع والمفهومة جيدًا، يتخذها وحده: تنظيم وصف العمل، وطرح أسئلة توضيحية، ومطابقة الموردين ودعوتهم، وتقييم اكتمال طلبات عروض الأسعار والعروض، وإبراز الأنظمة المنطبقة، وصياغة المراسلات، والأعمال التشغيلية الروتينية، مع تسجيل كل إجراء.', 'all', 'Arabic mirror of company_faq id 98', 98),
  (1011, 'كيف تجري مراقبة المحرك الذكي؟', 'يمرّ كل قرار عبر بوابة حوكمة ويُكتب في سجل غير قابل للتعديل؛ وتحتفظ الإجراءات الحساسة بصورة سابقة تتيح التراجع عنها؛ وتتابع فحوص السلامة والتقييمات ومدرّب مخصّص جودةَ الأداء باستمرار، مع تنبيهات تُظهر كل ما يستدعي الانتباه.', 'all', 'Arabic mirror of company_faq id 104', 104),
  (1012, 'كيف تُدار الصلاحيات؟', 'قاعدة البيانات مغلقة افتراضيًا، فلا شيء يُقرأ منها مباشرةً بمفتاح عام. وتمرّ كل عملية قراءة أو كتابة عبر دوال خلفية تتحقق من هويتكم ومما يُسمح لكم به (وصول قائم على الأدوار)، وتتطلب مناطق الإدارة مصادقة إضافية تشمل المصادقة متعددة العوامل.', 'all', 'Arabic mirror of company_faq id 118', 118),
  (1013, 'كيف تُحلَّل ملفات PDF؟', 'يستخرج المحرك الذكي محتوى ملفات PDF، سواء كانت مخططات أو جداول كميات أو عرض السعر لديكم، ليبني منها وصفًا أو عرضًا منظّمًا ونظيفًا، فيستخلص البنود والمواصفات ويحذف الهوية أو الأسعار عند الحاجة للحفاظ على السرية.', 'all', 'Arabic mirror of company_faq id 127', 127),
  (1014, 'كيف تُقاس جودة المورّد؟', 'بالنتائج الفعلية: تقييمات العملاء متعددة الأبعاد (التواصل والجودة والالتزام بالمواعيد والتوثيق وخدمة ما بعد البيع والامتثال)، وسجل المورّد في النزاعات، وسرعة استجابته، وجودة العروض التي يقدّمها، مجتمعةً في درجة سمعة يراها العملاء.', 'all', 'Arabic mirror of company_faq id 134', 134),
  (1015, 'ماذا يحدث إذا كان طلب عرض السعر غير مكتمل؟', 'يحوّل وكيل الاستقبال كلمات العميل وصوره إلى وصف منظّم، ويتحقق من اكتماله وفق دليل تأهيل الفئة. وإذا نقصت تفاصيل أساسية، لم يُعتمد الطلب جاهزًا ولم يُرسل إلى الموردين، ويُطلب من العميل استكمال المعلومات الناقصة (مع إمكانية التعديل خلال ساعة واحدة). ولا يدخل الطلب مرحلة المطابقة إلا بعد اكتماله بما يكفي للتسعير الدقيق، حمايةً للطرفين من المطابقات غير المناسبة.', 'all', 'Arabic mirror of company_faq id 145', 145),
  (1016, 'ما واجهات البرمجة المتاحة؟', 'تعمل QuotesDone على بنية خلفية آمنة تخصّها وحدها. وتتولّى Stripe معالجة المدفوعات، وما عداها يعمل خلف الكواليس. ولا توجد حتى الآن واجهة برمجة عامة أو للشركاء متاحة للعملاء أو الموردين؛ فكل التعامل يجري عبر التطبيق والبوابة. ويمكن طرح واجهة برمجة منشورة لاحقًا إذا وُجد طلب عليها.', 'all', 'Arabic mirror of company_faq id 157', 157),
  (1017, 'سياسة الأمن', 'الوصول مغلق افتراضيًا، مع إدارة محكومة بالأدوار ووصول خدمي بأقل صلاحية ممكنة؛ ويعمل منطق الأعمال كاملًا على الخادم، ولا تُكشف المفاتيح السرية أبدًا. والبيانات مشفّرة أثناء النقل وفي التخزين، ولا يجري الوصول إلى المستندات إلا عبر روابط موقّعة قصيرة العمر، ويراقب وكيل الأمن الوضع الأمني والمخاطر باستمرار. ولا يرى أي طرف سوى بياناته.', 'all', 'Arabic mirror of company_faq id 166', 166),
  (1018, 'هل ستتوسّع المنصة دوليًا؟', 'الأولوية الآن كسب سوق الإمارات وإثبات النموذج. والمنصة مبنية لتكون قابلة للتكيّف، إذ صُمّمت قاعدة معرفتها وفئاتها وقواعد الامتثال فيها بحيث يمكن إضافة ولايات قضائية جديدة، فالتوسّع الدولي، بدءًا بدول الخليج الأوسع، اتجاه طبيعي متى ترسّخ الأساس في الإمارات. وهو غير مفعّل بعد، وأي سوق جديدة ستنطلق بمعرفة تنظيمية محلية راسخة، لا بنسخ ولصق.', 'all', 'Arabic mirror of company_faq id 173', 173),
  (1019, 'ما هي القيم الأساسية للشركة؟', 'السرية وتحكّم المشتري (لا تواصل خارج المنصة قبل الاطلاع)؛ الصدق (لا يَعِد الوكلاء بما لا يتحقق ولا يختلقون شيئًا، وإجاباتهم مستندة إلى بيانات فعلية)؛ عروض أسعار عادلة قابلة للمقارنة من حيث الجودة؛ احترام المورّدين (مطابقات ذات صلة فقط واقتصاديات منصفة للبائع)؛ الثقة والمساءلة (كيان مرخّص، وموردون موثَّقون، ومحرّك ذكي قابل للتدقيق وللتراجع عن إجراءاته).', 'all', 'Arabic mirror of company_faq id 8', 8),
  (1020, 'هل يمكنني تعديل الطلب؟', 'نعم، يمكنكم تعديل الطلب خلال ساعة واحدة من إرساله. وبعد انقضاء هذه المهلة، إذا تغيّر أمر جوهري، أنشئوا طلبًا جديدًا ليقدّم الموردون عروضهم على النطاق الصحيح.', 'customer', 'Arabic mirror of company_faq id 19', 19),
  (1021, 'هل يمكنني إعادة فتح طلب؟', 'لا تتوفر إعادة الفتح؛ أنشئوا طلبًا جديدًا فحسب، ويقدّم الموردون عروض أسعار من جديد.', 'customer', 'Arabic mirror of company_faq id 25', 25),
  (1022, 'ماذا لو تغيّر مشروعي؟', 'إذا تغيّر مشروعكم خلال ساعة من الإرسال، عدّلوا الطلب مباشرة. وبخلاف ذلك أنشئوا طلبًا جديدًا بالنطاق المحدَّث ليأتي تسعير الموردين دقيقًا. أما إذا تغيّر بعد اطّلاعكم على بيانات مورّد، فنسّقوا التغييرات معه مباشرة عبر المنصة.', 'customer', 'Arabic mirror of company_faq id 35', 35),
  (1023, 'كيف أقدّم عروض الأسعار؟', 'تقدّمون عروضكم من بوابة الموردين. أدخلوا عرض سعر مفصّلًا ببنوده: العلامة والموديل، والمواصفات، والكميات، وأسعار الوحدة، إضافة إلى نطاق العمل ومدة التوريد وصلاحية العرض والضمان والشروط. ويصل عرضكم إلى العميل دون كشف هويتكم، وتبقى مخفية إلى أن يسدّد رسوم الاطلاع عليكم.', 'supplier', 'Arabic mirror of company_faq id 44', 44),
  (1024, 'متى أدفع؟', 'لا تدفعون شيئًا مقابل تقديم عرض سعر ولا عند الفوز، ولا توجد عمولة. والتسجيل مجاني لأول 1,000 مورّد يسجّلون، ويبقى هؤلاء مجانًا بصفة دائمة. ويدفع كل مورّد يسجّل بعدهم اشتراكًا سنويًا قدره 1,000 درهم إماراتي؛ ولا يوجد تاريخ بدء محدّد، إذ يسري الاشتراك اعتبارًا من التسجيل رقم 1,001 فصاعدًا. ويُسدَّد الاشتراك على بوابة الموردين عبر صفحة دفع آمنة من Stripe. والرسوم الأخرى الوحيدة الممكنة هي رسوم عدم الاستجابة إذا تجاهلتم عميلًا سدّد بالفعل رسوم الاطلاع على بياناتكم.', 'supplier', 'Arabic mirror of company_faq id 50', 50),
  (1025, 'هل يمكنني العمل في أكثر من فئة؟', 'نعم، يمكنكم تغطية عدة تخصصات أو فئات. احرصوا على اكتمال ملف قدراتكم ودقّته ليطابقكم المحرّك الذكي مع الأعمال المناسبة.', 'supplier', 'Arabic mirror of company_faq id 56', 56),
  (1026, 'هل يستطيع المحرّك الذكي تقدير الميزانيات؟', 'لا يختلق ميزانية أو سعرًا نيابة عنكم؛ فالموردون هم من يحدّدون السعر، وذكر الميزانية اختياري. لكنه يعرض نطاق ثقة سعرية (مدى معتاد مستمد من أعمال مماثلة) يتيح لكم تقدير مدى معقولية العروض التي تصلكم.', 'all', 'Arabic mirror of company_faq id 64', 64),
  (1027, 'ما الحقول الإلزامية؟', 'الأقسام المطلوبة لتلك الفئة، وهي عادة: نطاق العمل؛ وبنود العرض المفصّلة (جدول الكميات) مع العلامة والموديل والمواصفات والكميات وأسعار الوحدة؛ والمواد؛ ومدة التوريد؛ وصلاحية العرض؛ والضمان؛ وشروط الدفع؛ والاستثناءات. ولا يجتاز العرض معيار الجودة ولا يصل إلى العميل ما لم يتضمّن هذه العناصر.', 'all', 'Arabic mirror of company_faq id 70', 70),
  (1028, 'هل يستطيع المحرّك الذكي رفض عروض الأسعار؟', 'لا يرفضكم رفضًا مباشرًا، بل يطبّق معيار جودة. فالعرض الذي تقل درجة اكتماله عن الحد المطلوب يبقى مسوّدة مع إرشادات محدّدة لما ينقصه، ويصل إلى العميل فور استيفائه المعيار. وهذا يحمي الجميع: العملاء يحصلون على عروض كاملة، والموردون الجيدون لا تنافسهم عروض ناقصة بأسعار أقل.', 'all', 'Arabic mirror of company_faq id 76', 76),
  (1029, 'ما العلامات التجارية الموصى بها؟', 'QuotesDone محايدة تجاه العلامات التجارية، فلا تروّج لعلامة بعينها ولا ترتّبها. وما تحرص عليه هو أن تستوفي العلامة المعروضة المواصفات والمعايير والاعتمادات المطلوبة في الإمارات لعملكم؛ فالمورّد يقترح العلامة والاختيار لكم. وبهذا يبقى السوق عادلًا ومحايدًا.', 'all', 'Arabic mirror of company_faq id 82', 82),
  (1030, 'ما الاعتمادات المطلوبة؟', 'تختلف اعتمادات الجهات باختلاف نوع العمل وموقعه: هيئة كهرباء ومياه دبي DEWA (الأعمال الكهربائية والمرافق)، والدفاع المدني بدبي (الحريق والسلامة)، وبلدية دبي (البناء والصرف والمباني الخضراء)، ومؤسسة تنظيم الصناعات الأمنية SIRA (الأمن)، ووزارة الصناعة والتكنولوجيا المتقدمة MoIAT والإمارات للمواصفات والمقاييس ESMA (مطابقة المنتجات)، والهيئة العامة للطيران المدني GCAA (قرب المطارات)، وتراخيص Trakhees وسلطة دبي للتطوير DDA (المناطق الحرة)، وهيئة المعرفة والتنمية البشرية KHDA (المدارس والحضانات). ويحدّد المحرّك الذكي ما ينطبق منها على عملكم، أما الحصول عليها فمسؤولية المورّد أو الاستشاري.', 'all', 'Arabic mirror of company_faq id 88', 88),
  (1031, 'ما الذي لا يستطيع المحرّك الذكي البتّ فيه؟', 'كل ما هو حسّاس أو غير قابل للتراجع محجوز لقرار شخص لدينا: تحويل الأموال أو ردّها، ونشر المستندات القانونية أو التعاقدية، وتغيير التسعير أو السياسات، واعتماد المحتوى التنظيمي عالي المخاطر، وأي أمر لا يكون واثقًا منه. فهو يُعِدّ ويوصي، والاعتماد يعود إلى شخص.', 'all', 'Arabic mirror of company_faq id 99', 99),
  (1032, 'هل يمكن أن يخطئ المحرّك الذكي؟', 'نعم، فأي نظام عرضة للخطأ، وقد بُنيت QuotesDone على هذا الافتراض: استناد الإجابات إلى بيانات فعلية للحد من الأخطاء، ومعيار جودة لعروض الأسعار ولطلبات عروض الأسعار، واعتماد بشري لكل أمر حسّاس، وسجل تدقيق غير قابل للتعديل، وإمكانية التراجع عن الإجراءات الحسّاسة؛ فتُكتشف الأخطاء وتُحتوى وتُصحَّح.', 'all', 'Arabic mirror of company_faq id 105', 105),
  (1033, 'ما أنواع الملفات المقبولة؟', 'الصيغ الشائعة: الصور (JPG وPNG)، وملفات PDF، ورسومات الكاد (DWG وDXF، وتُحوَّل تلقائيًا لتصبح قابلة للقراءة). ويمكنكم رفع الصور والرسومات وجداول الكميات وعروض الأسعار بصيغة PDF.', 'all', 'Arabic mirror of company_faq id 122', 122),
  (1034, 'كيف يُرتَّب الموردون؟', 'الترتيب قائم على الجدارة، ولا يُشترى بالدفع أبدًا. فهو يعكس الأداء الفعلي: تقييمات العملاء، وسرعة الاستجابة، ونسبة الفوز، ومدى ملاءمة المورّد للعمل فعليًا؛ كما يوازن المحرّك الذكي في كل طلب بين القدرة والإمارات المخدومة ومدى تشابه العمل. فالموردون يرتقون بحُسن أدائهم.', 'all', 'Arabic mirror of company_faq id 129', 129),
  (1035, 'كيف تُحتسب تقييمات العملاء؟', 'بعد إتمام الصفقة يترك العميل تقييمًا متعدد الجوانب، ولا يحق التقييم إلا لعميل اطّلع فعلًا على بيانات المورّد وتعامل معه، فتأتي التقييمات حقيقية. وتغذّي هذه التقييمات درجة السمعة الإجمالية للمورّد.', 'all', 'Arabic mirror of company_faq id 135', 135),
  (1036, 'ماذا يحدث إذا لم يقبل أي مورّد؟', 'هناك حالتان. إذا لم يجد المحرّك مورّدًا مناسبًا فعلًا، فلا يراسل أحدًا عن قصد (ولا إرسال عشوائي أبدًا)، ويرفع إشارة داخلية بوجود فجوة تغطية تحدّد للفريق التخصص والإمارة المطلوب استقطاب موردين فيهما. وإذا طوبق الطلب مع موردين ولم يستجب أحد، فتُرصد الاستجابة ويبقى العميل على اطلاع، ويمكن توسيع الطلب أو تصعيده. ولا يُحال العميل أبدًا إلى مورّد عشوائي أو غير مناسب لمجرد ملء المكان.', 'all', 'Arabic mirror of company_faq id 146', 146),
  (1037, 'سياسة انضمام الموردين', 'يسجّل الموردون بأنفسهم أو يطالبون بملف قائم، ويقدّمون الرخصة التجارية ومستندات «اعرف عميلك»، ويجري توثيقهم قبل التفعيل (خلال 3 أيام عمل كحد أقصى، ولا تُمنح الموافقة تلقائيًا). والقبول قائم على الجدارة؛ فلا ترتيب مدفوع ولا إعلانات. والتسجيل مجاني لأول 1,000 مورّد مسجّل، ويبقون مجانًا بصفة دائمة، ويدفع كل مورّد بعدهم اشتراكًا سنويًا قدره 1,000 درهم إماراتي، دون تاريخ بدء محدّد.', 'all', 'Arabic mirror of company_faq id 159', 159),
  (1038, 'سياسة الإيقاف', 'الإيقاف (حجب المطابقة) تعليق قابل للرجوع يوقف المطابقات الجديدة وتقديم عروض الأسعار، أما الحظر فيُخرج الطرف من السوق. ومن أسبابه: مخالفات الامتثال (مثل انتهاء صلاحية الرخصة)، وتكرار عدم الاستجابة، والمستحقات غير المسدَّدة، ومخالفات السياسات والسلوك. وتُسجَّل الإجراءات مع سببها وتُطبَّق بصلاحية إدارية، وتعود العضوية بعد معالجة المخالفة.', 'all', 'Arabic mirror of company_faq id 168', 168),
  (1039, 'هل ستُدعَم صناعات أخرى؟', 'نعم، فالمنصة مصمَّمة لتوسيع تغطيتها للفئات. فحين يسجّل مورّد تخصصًا لم تعرفه QuotesDone من قبل، يستطيع المحرّك الذكي إنشاء وكيل فئة جديد بأسئلة التأهيل والمعرفة المناسبة (باعتماد بشري قبل تفعيل تلك المعرفة)، فتتسع التغطية دون المساس بالجودة. ومع الوقت يمتد ذلك إلى مزيد من أعمال البناء والتشطيبات والأعمال الكهروميكانيكية وإدارة المرافق وما يتصل بها من تخصصات الأعمال، ثم إلى صناعات مجاورة كلما ظهر الطلب، مستندًا دائمًا إلى متطلبات حقيقية وموثَّقة لكل مجال.', 'all', 'Arabic mirror of company_faq id 174', 174)
  ) as v(sort, question, answer, audience, note, en_id)
-- THE ID IS READ OUT OF source_note AND COMPARED AS A NUMBER, never matched with a trailing %.
-- Review of this PR, 22 Sep 2026: the first version of this guard used
--   source_note like 'Arabic mirror of company_faq id ' || v.en_id::text || '%'
-- and the % made "id 2" match the twin of id 26, so the insert would have SILENTLY DROPPED five
-- answers it believes it wrote — ids 2, 3, 8, 9 and 50 — while the verdict below, carrying the same
-- prefix match, could not see the miss. Seven rows are expected not to insert; two of them
-- correctly (133 and 500 already have twins) and, with this guard, no others.
 where not exists (
   select 1 from public.company_faq f
    where f.language = 'ar'
      and (substring(f.source_note from 'company_faq id ([0-9]+)'))::int = v.en_id)
   and exists (
   select 1 from public.company_faq e
    where e.id = v.en_id and e.language = 'en' and e.public and e.status = 'approved');

-- The verdict as a ROW (no raise: a data file must not roll itself back). It reads the id the same
-- way the guard does — as a NUMBER out of source_note — because a verdict that repeats the guard's
-- own mistake can only ever agree with it.
select case when (select count(*) from public.company_faq f
                    where f.language = 'en' and f.public and f.status = 'approved'
                      and not exists (select 1 from public.company_faq m
                                       where m.language = 'ar' and m.status = 'approved' and m.public
                                         and (substring(m.source_note from 'company_faq id ([0-9]+)'))::int = f.id)) = 0
            then 'PROBE OK — every public approved English FAQ has an approved public Arabic twin ('
                 || (select count(*)::text from public.company_faq where language = 'ar' and status = 'approved' and public)
                 || ' Arabic records)'
            else 'PROBE FAILED — English FAQs still without an Arabic twin: ' ||
                 (select string_agg(f.id::text, ', ' order by f.id) from public.company_faq f
                   where f.language = 'en' and f.public and f.status = 'approved'
                     and not exists (select 1 from public.company_faq m
                                      where m.language = 'ar' and m.status = 'approved' and m.public
                                        and (substring(m.source_note from 'company_faq id ([0-9]+)'))::int = f.id))
       end as probe_verdict;
